export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying resource type which paigo connects to. Default is s3.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public datastoreType?: SupportedDatastores;

    /**
     *
     * Whether paigo is hosting the ingestion endpoint, or it is hosted by the client. Optional, default is `true`.
     * @example 'true'
     */
    @IsString()
    @IsOptional()
    public paigoHosted?: 'true';

    /**
     *
     * What is the cloud environment associated with the ingestion endpoint. Optional, default is `aws`.
     * @example "aws"
     */
    @IsEnum(supportedCloudPlatforms)
    @IsOptional()
    public hostedCloud?: supportedCloudPlatforms;

    /**
     * The Unqiue ID for the cloud env where the resource is hosted. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    public cloudId: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const { cloudId, hostedCloud, paigoHosted, datastoreType, businessID } = datastoreAccessInformation;
            this.cloudId = cloudId;
            this.hostedCloud = hostedCloud ? hostedCloud : supportedCloudPlatforms.aws;
            this.paigoHosted = paigoHosted ? paigoHosted : 'true';
            this.datastoreType = datastoreType ? datastoreType : SupportedDatastores.s3;
            this.businessID = businessID;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { datastoreType: supportedDbs, paigoHosted, hostedCloud, cloudId } = datastoreAccessInformation;
            if (supportedDbs) influxPoint.tag('supportedDbs', supportedDbs);
            if (paigoHosted) influxPoint.tag('paigoHosted', paigoHosted);
            if (hostedCloud) influxPoint.tag('hostedCloud', hostedCloud);
            if (cloudId) influxPoint.tag('cloudId', cloudId);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        datastoreType,
        paigoHosted,
        hostedCloud,
        cloudId,
        businessID,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            datastoreType,
            paigoHosted,
            hostedCloud,
            cloudId,
            businessID,
        });
    }
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, cloudId, datastoreType, businessID } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3) {
            try {
                // Add the cloudId as a root account on the policy of the S3 bucket, two hardcoded buckets for now: paigo-usage-record-dlq-bucket and paigo-usage-record-dump-bucket

                // Get the current policy of the bucket
                const s3 = new S3({});
                const params = {
                    Bucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                };
                const policy = await s3.getBucketPolicy(params);
                const policyJson = JSON.parse(policy.Policy);
                const statement = policyJson.Statement;
                const rootAccount = {
                    Sid: `RootAccount-${businessID}`,
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${cloudId}:root`,
                    },
                    Action: ['s3:GetObject', 's3:PutObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`],
                };
                statement.push(rootAccount);
                const newPolicy = { ...policyJson };
                newPolicy.Statement = statement;
                const newParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                    Policy: JSON.stringify(newPolicy),
                };
                await s3.putBucketPolicy(newParams);
                // Same for DLQ
                const dlqParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                };
                const dlqPolicy = await s3.getBucketPolicy(dlqParams);
                const dlqPolicyJson = JSON.parse(dlqPolicy.Policy);
                const dlqStatement = dlqPolicyJson.Statement;
                const rootAccountForDLQ = {
                    Sid: `RootAccount-${businessID}`,
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${cloudId}:root`,
                    },
                    Action: ['s3:GetObject'], // Only need read for DLQ
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`],
                };
                dlqStatement.push(rootAccountForDLQ);
                const newDLQPolicy = { ...dlqPolicyJson };
                newDLQPolicy.Statement = dlqStatement;
                const newDLQParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                    Policy: JSON.stringify(newDLQPolicy),
                };
                await s3.putBucketPolicy(newDLQParams);
            } catch (e) {
                if (e?.Code === 'MalformedPolicy') {
                    throw new BadRequestException(`CloudId: ${cloudId} is invalid`);
                } else {
                    throw e;
                }
            }
        }
    }
}

arguments.newString:
export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * Access information for datastore-based measurement (S3 ingestion).
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying platform Paigo connects to. Default is s3.
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores | string;

    /**
     * Customer AWS account ID trusted to assume the ingestion role.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty()
    public accountId: string;

    /**
     * AWS region for ingestion resources. Default is us-east-1.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public region?: string;

    /**
     * IAM role ARN provisioned for the customer to assume when writing usage data.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * External ID required when assuming the provisioned IAM role.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * S3 URI prefix for usage ingestion.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * S3 URI prefix for the dead-letter queue.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.accountId = accountId;
            this.region = region ? region : 'us-east-1';
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } = datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        });
    }

    private static buildTrustPolicy(accountId: string, externalId: string) {
        return JSON.stringify({
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        });
    }

    private static buildPermissionsPolicy(businessID: string) {
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        return JSON.stringify({
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}/${businessID}/*`],
                },
                {
                    Sid: 'IngestionList',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
                {
                    Sid: 'DlqAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:ListBucket'],
                    Resource: [
                        `arn:aws:s3:::${dlqBucket}`,
                        `arn:aws:s3:::${dlqBucket}/${businessID}/*`,
                    ],
                },
            ],
        });
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { accountId, businessID, measurementId, platform, region } = dbAccessInformation;
        const resolvedPlatform = platform ? platform : SupportedDatastores.s3;
        const resolvedRegion = region ? region : process.env.AWS_REGION || 'us-east-1';

        if (resolvedPlatform.toLowerCase() !== SupportedDatastores.s3) {
            throw new BadRequestException(`Unsupported datastore platform: ${resolvedPlatform}`);
        }

        const externalId = uuidv4();
        const roleName = `datastore-${businessID}-${measurementId}`;
        const iam = new IAMClient({ region: resolvedRegion });

        try {
            const createRoleResponse = await iam.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: DatastoreAccessInformation.buildTrustPolicy(accountId, externalId),
                    Description: `Paigo S3 datastore ingestion role for business ${businessID}`,
                })
            );

            await iam.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: `${roleName}-policy`,
                    PolicyDocument: DatastoreAccessInformation.buildPermissionsPolicy(businessID),
                })
            );

            const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
            const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
            const iamRoleArn = createRoleResponse.Role?.Arn;

            dbAccessInformation.platform = resolvedPlatform as SupportedDatastores;
            dbAccessInformation.region = resolvedRegion;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = iamRoleArn;
            dbAccessInformation.ingestion = `s3://${ingestionBucket}/${businessID}/`;
            dbAccessInformation.dlq = `s3://${dlqBucket}/${businessID}/`;

            return dbAccessInformation;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { accountId, externalId, iamRoleArn, region, businessID, measurementId } = dbAccessInformation;
        if (!iamRoleArn || !externalId) {
            throw new BadRequestException('Cannot update datastore access without an existing role and externalId');
        }

        const resolvedRegion = region ? region : process.env.AWS_REGION || 'us-east-1';
        const roleName =
            iamRoleArn.split('/').pop() || `datastore-${businessID}-${measurementId}`;
        const iam = new IAMClient({ region: resolvedRegion });

        await iam.send(
            new UpdateAssumeRolePolicyCommand({
                RoleName: roleName,
                PolicyDocument: DatastoreAccessInformation.buildTrustPolicy(accountId, externalId),
            })
        );

        return dbAccessInformation;
    }
}

